package com.aistock.market.alert;
import com.aistock.common.*;import com.aistock.market.marketlifecycle.*;import com.aistock.market.ingestion.CandidateRequestFilter;import com.fasterxml.jackson.databind.*;import java.util.*;import java.time.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AlertLocalUseHttpTest {
 @Test void onlyAuthenticatedAlertPrepareMovesAdmissionToService()throws Exception{var lifecycle=mock(MarketLifecycleService.class);var gate=new MarketEvidenceGate(lifecycle,true);var service=mock(AlertEvidenceService.class);var json=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);var mvc=MockMvcBuilders.standaloneSetup(new AlertEvidenceController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new CandidateRequestFilter("private",4096),new MarketEvidenceFilter(gate,json,false,true)).build();var r=new AlertEvidenceRecords.Request(UUID.randomUUID(),"SH600030",UUID.randomUUID(),LocalDate.parse("2026-10-09"),Instant.parse("2026-10-10T06:01:30Z"));String body=json.writeValueAsString(r);String path="/internal/v1/market/alert-evidence/prepare";mvc.perform(post(path).contentType("application/json").content(body)).andExpect(status().isUnauthorized());verifyNoInteractions(service,lifecycle);when(service.prepare(any())).thenReturn(new AlertEvidenceRecords.Receipt(r.operationId(),"FAILED",null,"SOURCE_UNAVAILABLE"));mvc.perform(post(path).header("X-Service-Token","private").contentType("application/json").content(body)).andExpect(status().isOk());verify(service,times(1)).prepare(any());mvc.perform(get("/internal/v1/market/alert-evidence/versions/"+UUID.randomUUID()).header("X-Service-Token","private")).andExpect(status().isBadRequest());var off=MockMvcBuilders.standaloneSetup(new AlertEvidenceController(service)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new CandidateRequestFilter("private",4096),new MarketEvidenceFilter(gate,json,false,false)).build();off.perform(post(path).header("X-Service-Token","private").contentType("application/json").content(body)).andExpect(status().isBadRequest());verify(service,times(1)).prepare(any());verifyNoInteractions(lifecycle);}
}
